import { Router } from 'express';
import { z } from 'zod';
import { createLogger } from '../index-core';
import { TelemetryService } from '../services/TelemetryService';
import {
  SupportTicketDeliveryService,
  SupportTicketService,
} from '../services/SupportTicketService';
import { errorMessage } from '../utils/errorMessage';
import type { SupportTicketErrorResponse } from '../types/api-responses';

const log = createLogger('SupportRoutes');
const SUPPORT_TICKET_FAILURE_DETAILS = 'Please try again in a few minutes.';

const SupportTicketMetadataSchema = z
  .object({
    posthogSessionId: z.string().trim().min(1).max(200).optional(),
    posthogDistinctId: z.string().trim().min(1).max(200).optional(),
    appVersion: z.string().trim().min(1).max(100).optional(),
    appEnvironment: z.string().trim().min(1).max(100).optional(),
    pageUrl: z.string().trim().min(1).max(2000).optional(),
    userAgent: z.string().trim().min(1).max(1000).optional(),
    submittedAt: z.string().trim().min(1).max(100).optional(),
  })
  .strict()
  .optional();

const SupportTicketRequestSchema = z
  .object({
    type: z.enum(['issue', 'feedback']),
    message: z.string().trim().min(1).max(5000),
    metadata: SupportTicketMetadataSchema,
    contactEmail: z.string().trim().email().max(320).optional(),
  })
  .strict();

export const createSupportRouter = (
  telemetry?: TelemetryService,
  deliveryService: SupportTicketDeliveryService = new SupportTicketService(),
) => {
  const router = Router();

  router.post('/support/tickets', async (req, res) => {
    const parseResult = SupportTicketRequestSchema.safeParse(req.body);
    if (!parseResult.success) {
      return res.status(400).json({
        error: 'Invalid support ticket payload',
        details: parseResult.error.flatten(),
      } satisfies SupportTicketErrorResponse);
    }

    const request = parseResult.data;

    try {
      const result = await deliveryService.submitTicket(request);

      telemetry?.track('support_ticket_submitted', {
        ticket_type: request.type,
        has_contact_email: Boolean(request.contactEmail),
        has_posthog_session_id: Boolean(request.metadata?.posthogSessionId),
      });

      return res.json({
        success: true,
        ticketId: result.ticketId,
      });
    } catch (error) {
      const message = errorMessage(error, 'Unknown submission error');
      log.error('Failed to submit support ticket:', message);

      telemetry?.track('support_ticket_submit_failed', {
        ticket_type: request.type,
        has_contact_email: Boolean(request.contactEmail),
        error: message,
      });

      return res.status(500).json({
        error: 'Failed to submit support ticket',
        details: SUPPORT_TICKET_FAILURE_DETAILS,
      } satisfies SupportTicketErrorResponse);
    }
  });

  return router;
};
